import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

/**
 * 【樱华少女的秘密季节】MVU 变量结构定义
 * 
 * 核心逻辑说明：
 * 1. stat_data.identity.exposure_risk: 暴露风险。达到100则触发身份暴露结局。
 * 2. stat_data.identity.filter_strength: 认知滤镜。越高则NPC越倾向于将男性化行为解释为“帅气”。
 * 3. stat_data.body.fixer_integrity: 固定器完好度。长时间未维护会下降，导致暴露风险上升。
 * 4. $开头字段: 仅供状态栏显示使用，AI禁止通过更新规则修改。
 * 5. _开头字段: 元数据，AI只读。
 */

const Schema = zod.object({
  stat_data: zod.object({
    // 身份与伪装核心
    identity: zod.object({
      exposure_risk: zod.number().min(0).max(100).describe("身份暴露风险值，0为安全，100为彻底暴露"),
      filter_strength: zod.number().min(0).max(100).describe("NPC认知滤镜强度，决定了NPC对违和行为的包容度"),
      $risk_status: zod.string().describe("派生：根据暴露风险生成的文字评价"),
      $identity_label: zod.string().describe("派生：当前在校园内的公众形象称号")
    }),

    // 身体状态与装备维护
    body: zod.object({
      fixer_integrity: zod.number().min(0).max(100).describe("硅胶固定器的物理完好度"),
      discomfort_level: zod.number().min(0).max(100).describe("因长期佩戴固定器产生的不适感/皮肤红肿程度"),
      stamina: zod.number().min(0).max(100).describe("当前的体力储备"),
      $body_warning: zod.string().describe("派生：身体状况的预警信息")
    }),

    // 社交与人际关系
    social: zod.object({
      popularity: zod.number().min(0).max(100).describe("在樱华女子学院的人气值"),
      clique_rank: zod.string().describe("当前所处的社交阶层（如：边缘、普通、核心、学生会）"),
      haruko_bond: zod.object({
        favor: zod.number().describe("佐仓春子对你的好感度"),
        intimacy: zod.number().describe("佐仓春子与你的亲密度/肢体接触频率")
      })
    }),

    // 场景与环境元数据
    environment: zod.object({
      time_slot: zod.enum(["早课", "午休", "下午课", "部活时间", "黄昏", "深夜"]).describe("当前的校园时间段"),
      location: zod.string().describe("当前所在的具体位置"),
      _current_day: zod.number().describe("入学后的总天数计数")
    })
  })
});

$(() => { 
  registerMvuSchema(Schema); 
});

