.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
  margin-bottom: 8px;
}

.nested-group {
  margin-left: 12px;
  padding-left: 12px;
  border-left: 1px dashed var(--mvu-border-color);
  margin-top: 8px;
}

.stat-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 11px;
  color: var(--mvu-text-sub);
}

.stat-value {
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.value-number {
  font-family: "Courier New", Courier, monospace;
  font-weight: bold;
  color: var(--mvu-text-main);
}

.value-true { color: var(--mvu-true-color); font-weight: bold; }
.value-false { color: var(--mvu-false-color); }
.value-text { color: var(--mvu-text-main); }

.progress-bar {
  width: 100%;
  height: 6px;
  background: #f0f0f0;
  border-radius: 3px;
  overflow: hidden;
  margin-top: 2px;
}

.progress-bar-fill {
  height: 100%;
  background: var(--mvu-safe-fill);
  border-radius: 3px;
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1), background-color 1s;
}

.indent-1 { padding-left: 4px; }
.indent-2 { padding-left: 12px; }
.indent-3 { padding-left: 20px; }
.indent-4 { padding-left: 28px; }

.status-footer {
  padding: 8px 16px;
  background: #f8f9fa;
  border-top: 1px solid var(--mvu-border-color);
  font-size: 10px;
  color: var(--mvu-text-sub);
  display: flex;
  justify-content: space-between;
}

.loading-state {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 80px;
  color: var(--mvu-text-sub);
  font-size: 12px;
  font-style: italic;
}

.flash-update {
  animation: mvu-pulse 0.4s ease-out;
}

@keyframes mvu-pulse {
  0% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.01); opacity: 0.8; }
  100% { transform: scale(1); opacity: 1; }
}

mvuTabStatusBarModules.step5:
function _getVars() {
  try {
    if (typeof getVariables === "function") {
      var r = getVariables({
        type: "message",
        message_id: "latest"
      });
      if (r && typeof r === "object") return r;
    }
  } catch (e) {}
  try {
    return getAllVariables() || {};
  } catch (e2) {
    return {};
  }
}

function refreshStatus() {
  var allVars = _getVars();
  var sourceData = _.get(allVars, "stat_data", {});
  var htmlStr = '';

  function renderTree(obj, level) {
    level = level || 0;
    var indentClass = "indent-" + Math.min(level, 4);
    var itemsHtml = '';
    Object.keys(obj || {}).forEach(function(key) {
      var value = obj[key];
      if (key.indexOf("_") === 0) return;
      if (key.indexOf("$") === 0 && !(/(状态|等级|评价|称号|警告|现状)$/.test(key))) return;
      var isPlainObj = value !== null && typeof value === "object" && !Array.isArray(value);
      if (isPlainObj) {
        if (itemsHtml) {
          htmlStr += '<div class="stat-grid ' + indentClass + '">' + itemsHtml + '</div>';
          itemsHtml = '';
        }
        if (level > 0) htmlStr += '<div class="nested-group ' + indentClass + '"><div class="category-title">' + key + '</div>';
        renderTree(value, level + 1);
        if (level > 0) htmlStr += '</div>';
        return;
      }
      itemsHtml += '<div class="stat-item"><span class="stat-label">' + key + '</span><span class="stat-value">';
      if (typeof value === "number") {
        itemsHtml += '<span class="value-number">' + value + '</span>';
        var pct = Math.max(0, Math.min(100, Number(value) || 0));
        itemsHtml += '<div class="progress-bar"><div class="progress-bar-fill" style="width:' + pct + '%"></div></div>';
      } else if (typeof value === "boolean") {
        itemsHtml += value ? '<span class="value-true">✓</span>' : '<span class="value-false">✕</span>';
      } else if (Array.isArray(value)) {
        itemsHtml += '<span class="value-text">[' + value.join(', ') + ']</span>';
      } else {
        itemsHtml += '<span class="value-text">' + String(value == null ? '' : value) + '</span>';
      }
      itemsHtml += '</span></div>';
    });
    if (itemsHtml) htmlStr += '<div class="stat-grid ' + indentClass + '">' + itemsHtml + '</div>';
  }
  renderTree(sourceData, 0);
  var root = document.getElementById("render-root");
  if (root) {
    root.innerHTML = htmlStr;
    try {
      root.classList.add("flash-update");
    } catch (e) {}
    setTimeout(function() {
      try {
        root.classList.remove("flash-update");
      } catch (e) {}
    }, 300);
  }
}

mvuTabStatusBarModules.step6:
$(async function() {
  try {
    await waitGlobalInitialized("Mvu");
    var _waitCount = 0;
    while (!_.has(_getVars(), "stat_data") && _waitCount < 15) {
      await new Promise(function(r) { setTimeout(r, 1000); });
      _waitCount++;
    }
    refreshStatus();
    var _sbTimer = setInterval(refreshStatus, 2000);
    document.addEventListener("visibilitychange", function() {
      if (document.hidden) { clearInterval(_sbTimer); _sbTimer = null; }
      else if (!_sbTimer) { _sbTimer = setInterval(refreshStatus, 2000); }
    });
    window.addEventListener("pagehide", function() { if (_sbTimer) { clearInterval(_sbTimer); _sbTimer = null; } });
    try {
      if (typeof eventOn === "function" && typeof Mvu !== "undefined" && Mvu && Mvu.events) {
        eventOn(Mvu.events.VARIABLE_INITIALIZED, refreshStatus);
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, refreshStatus);
      }
    } catch(evErr) {}
  } catch(err) {
    console.warn('[statusbar] init failed:', err && err.message);
    try { var root = document.getElementById("render-root") || document.body; if (root) root.innerHTML = '<div style="padding:12px;color:#fca5a5;font-size:12px">初始化失败：' + (err && err.message ? err.message : String(err)) + '</div>'; } catch(e) {}
  }
});

